/// <summary>
/// PricingAttribute of table <c>InventTable</c> field ScrapConst.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableScrapConst extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, ScrapConst);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    InventTable inventTable;

    while select inventTable
        group by ScrapConst
    {
        if (! ret.in(inventTable.ScrapConst))
        {
            ret.add(inventTable.ScrapConst);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, ScrapConst));
    qbr.value(queryValue(_value));
}
